import{_ as t,o,c as a,a5 as n}from"./chunks/framework.CiMLk4oN.js";const p=JSON.parse('{"title":"extraction_timeout is a liveness (no-progress) timeout, not a total cap","description":"","frontmatter":{"status":"accepted"},"headers":[],"relativePath":"adr/0001-extraction-timeout-liveness.md","filePath":"adr/0001-extraction-timeout-liveness.md"}'),i={name:"adr/0001-extraction-timeout-liveness.md"};function s(r,e,l,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="extraction-timeout-is-a-liveness-no-progress-timeout-not-a-total-cap" tabindex="-1"><code>extraction_timeout</code> is a liveness (no-progress) timeout, not a total cap <a class="header-anchor" href="#extraction-timeout-is-a-liveness-no-progress-timeout-not-a-total-cap" aria-label="Permalink to &quot;`extraction_timeout` is a liveness (no-progress) timeout, not a total cap&quot;">​</a></h1><p>TORCH extractions for large cohorts (100k+ patients) legitimately run for hours, but the <code>extraction_timeout</code> config (default 30 min) was a hard total cap measured from the start of each poll run — so a healthy long job was killed for being long, and resuming only restarted the same 30-minute clock. We redefine <code>extraction_timeout</code> as the maximum time aether will wait <strong>since last contact with TORCH</strong>, reset on every <code>202</code>/<code>200</code> poll response. A healthy job (polling at least every <code>max_polling_interval</code>) never trips it; aether only gives up when TORCH goes silent.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Redefine the existing <code>extraction_timeout</code> key (chosen)</strong> — no new config surface; the new meaning is what operators actually want. Cost: a silent behavior change for anyone who relied on it as a total-cost ceiling (rare; called out in the config comment and changelog).</li><li><strong>Add a new <code>poll_liveness_timeout</code> key, keep <code>extraction_timeout</code> as a total cap</strong> — cleaner naming but adds config surface and a deprecation story for a meaning almost nobody wants.</li><li><strong>Liveness timeout plus a large absolute ceiling</strong> — rejected for now; the only case it guards is a TORCH job stuck returning <code>202</code> forever (a TORCH bug), which an operator can interrupt manually.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A TORCH job that stays responsive (<code>202</code>) but never completes will be polled indefinitely until manually interrupted. Accepted as a TORCH-side fault, not aether&#39;s to bound.</li></ul>',6)])])}const h=t(i,[["render",s]]);export{p as __pageData,h as default};
